package com.example.workout.workout.entity; import jakarta.persistence.*; import lombok.*;
@Entity @Table(name="workout_laps") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder(setterPrefix="with") public class WorkoutLapEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="workout_id",nullable=false) private WorkoutEntity workout; @Column(nullable=false) private Integer position; private Integer distanceMeters; private Integer durationSeconds; private Integer paceSecondsPerKm; private Integer averageHeartRate; private Integer maxHeartRate; private Integer averageCadence; private Integer averagePowerWatts; private Integer elevationGainMeters; private Integer elevationLossMeters; }
